style.css:
@-moz-document domain("pinterest.com") {
html, body {
    height: 100%;
    margin: 0;
    background: #000 !important; /* bordes negros */
  }

  /* Fondo central con imagen de leopardo */
  body::before {
    content: "";
    position: fixed;
    top: 40px;
    bottom: 40px;
    left: 40px;
    right: 40px;
    background-image: url("https://static4.depositphotos.com/1019221/338/i/450/depositphotos_3382879-stock-illustration-leopard-background.jpg");
    background-size: cover;
    background-position: center;
    border-radius: 40px;
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.8);
    z-index: -1;
  }

  /* Forzar transparencia de TODO lo que cubra el fondo */
  #__next,
  #root,
  .App,
  .AppContainer,
  [data-test-id="app-root"],
  div[role="main"],
  main,
  section,
  .tBJ,
  .zI7,
  .hCL,
  .Jea,
  .X8D {
    background: transparent !important;
  }

  /* Header y buscador transparentes */
  header,
  .Header,
  .topNav,
  [data-test-id="header"],
  input[type="search"],
  .SearchBox,
  .searchBox {
    background: transparent !important;
    color: #fff !important;
    border: none !important;
  }

  header *,
  .Header *,
  .topNav *,
  .SearchBox * {
    color: #fff !important;
    fill: #fff !important;
  }

  input[type="search"]::placeholder {
    color: #eee !important;
  }

  /* Quitar cualquier sombra o color detrás de los pines */
  .Pin, .Board, .gridItem, .searchResult, .VbI, .MIw, .tBJ {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Ajuste de scrollbar negro elegante */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background: #000;
    border-radius: 8px;
  }
}
